#!/usr/bin/env python3
"""gen_tabsp.py tab.s tabsp.s
Convert the translator's dispatch table source (tab.s: eight tables of 16384 `.long` entries, mostly `.long rt_unk_ent`, written with `.rept`) into a sparse
list of (table<<16 | index, address) pairs: 8 bytes per translated entry instead of 64 KB per table on the disk.  platform-a1200/tabs.c expands it at boot."""
import re, sys
src = open(sys.argv[1]).read().split('\n')
names = ['tab_win0','tab_win1','tab_win2','tab_win3','tab_win4','tab_win5','tab_win6','tab_fix']
cur = -1; pos = 0; ents = []; total = [0]*8
def entry(sym):
    global pos
    if sym != 'rt_unk_ent': ents.append((cur, pos, sym))
    pos += 1; total[cur] += 1
i = 0
while i < len(src):
    l = src[i].split('|')[0].strip(); i += 1
    m = re.match(r'(\w+):$', l)
    if m and m.group(1) in names: cur = names.index(m.group(1)); pos = 0; continue
    m = re.match(r'\.long\s+(\S+)$', l)
    if m: entry(m.group(1)); continue
    m = re.match(r'\.rept\s+(\d+)$', l)
    if m:
        n = int(m.group(1)); body = []
        while src[i].strip() != '.endr': body.append(src[i].strip()); i += 1
        i += 1
        for _ in range(n):
            for b in body:
                mm = re.match(r'\.long\s+(\S+)$', b); assert mm, b
                entry(mm.group(1))
        continue
assert all(t == 16384 for t in total), total
with open(sys.argv[2], 'w') as f:
    f.write('| generated by tools/gen_tabsp.py - sparse dispatch tables\n\t.section .rodata\n\t.even\n\t.globl tabsp_n, tabsp\ntabsp_n:\n\t.long %d\ntabsp:\n' % len(ents))
    for t, p, s in ents: f.write('\t.long 0x%x, %s\n' % ((t << 16) | p, s))
print('%d translated entries' % len(ents))
